<?php
namespace Database\Seeders;use App\Models\SupportTicket;use App\Models\User;use Illuminate\Database\Seeder;
class SupportTicketSeeder extends Seeder {public function run():void{User::whereNotNull('project_id')->each(function($u){if(SupportTicket::where('project_id',$u->project_id)->where('user_id',$u->id)->exists())return;foreach([['Billing & Accounting','Invoice question','Normal','In Progress',true],['Report an Issue','Login error','High','Awaiting Response',false],['Share an Idea','New report option','Normal','Resolved',true]]as$i=>$x){SupportTicket::create(['project_id'=>$u->project_id,'user_id'=>$u->id,'ticket_no'=>'SUP-'.now()->format('Y').'-'.str_pad((string)(($u->id*100)+$i+1),4,'0',STR_PAD_LEFT),'ticket_type'=>$x[0],'requested_by'=>$u->name,'email'=>$u->email,'phone'=>$u->phone,'subject'=>$x[1],'description'=>'Support request details.','priority'=>$x[2],'status'=>$x[3],'responded_by'=>$x[4]?'Support Team':null,'responded_position'=>$x[4]?'Support Specialist':null,'responded_at'=>$x[4]?now()->subDays($i+1):null]);}});}}
